"use client";

import type { ComponentProps } from "react";
import { Button } from "@/components/ui/button";
import "./supervisor-brand-button.css";

export type SupervisorBrandButtonProps = ComponentProps<typeof Button>;

export function SupervisorBrandButton(props: SupervisorBrandButtonProps) {
  return <Button {...props} data-supervisor-brand="" data-supervisor-brand-size={props.size ?? "default"} />;
}

[data-slot="button"][data-supervisor-brand] {
  border: 1px solid #e6471f;
  border-radius: 5px;
  background: #ff5125;
  color: #ffffff;
  font-family: var(--font-geist-mono, "Geist Mono Variable"), "Geist Mono", ui-monospace, monospace;
  font-weight: 500;
  text-transform: uppercase;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 28%), 0 2px 3px rgb(143 39 10 / 12%), 0 6px 14px rgb(255 81 37 / 14%);
  transition: background-color 320ms, border-color 320ms, color 320ms, opacity 320ms, transform 200ms, translate 200ms, scale 200ms, box-shadow 320ms;
  transition-timing-function: cubic-bezier(.22, 1, .36, 1);
}

[data-slot="button"][data-supervisor-brand][data-supervisor-brand-size="default"] {
  height: 44px;
  padding-inline: 16px;
  gap: 8px;
  font-size: 14px;
}

@media (hover: hover) {
  [data-slot="button"][data-supervisor-brand]:hover:not(:disabled):not([aria-disabled="true"]) {
    background: #f0441b;
    translate: 0 -1px;
    box-shadow: inset 0 1px 0 rgb(255 255 255 / 28%), 0 3px 5px rgb(143 39 10 / 14%), 0 8px 18px rgb(255 81 37 / 20%);
  }
}

[data-slot="button"][data-supervisor-brand]:active:not(:disabled):not([aria-disabled="true"]) {
  background: #e8441c;
  translate: 0 2px;
  scale: .98;
  box-shadow: inset 0 2px 4px rgb(112 28 5 / 24%), inset 0 -1px 0 rgb(255 255 255 / 12%), 0 1px 2px rgb(143 39 10 / 10%);
  transition-duration: 75ms;
}

[data-slot="button"][data-supervisor-brand]:focus-visible {
  outline: 2px solid #1886e2;
  outline-offset: 2px;
}

[data-slot="button"][data-supervisor-brand]:is(:disabled, [aria-disabled="true"]) {
  border-color: var(--border, #e8e8e8);
  background: var(--muted, #f4f4f4);
  color: var(--muted-foreground, #666666);
  box-shadow: none;
  cursor: default;
  opacity: 1;
  translate: none;
  scale: none;
}

[data-slot="button"][data-supervisor-brand] [data-supervisor-brand-arrow] {
  transform: rotate(0deg);
  transition: transform 320ms cubic-bezier(.22, 1, .36, 1);
}

[data-slot="button"][data-supervisor-brand] [data-supervisor-brand-label] {
  display: inline-grid;
  overflow: hidden;
}

[data-slot="button"][data-supervisor-brand] [data-supervisor-brand-state] {
  grid-area: 1 / 1;
  transition: opacity 320ms cubic-bezier(.22, 1, .36, 1), transform 320ms cubic-bezier(.22, 1, .36, 1);
}

[data-slot="button"][data-supervisor-brand] [data-supervisor-brand-state="active"] {
  opacity: 1;
  transform: translateY(0);
}

[data-slot="button"][data-supervisor-brand] [data-supervisor-brand-state="selected"] {
  opacity: 0;
  transform: translateY(60%);
}

[data-slot="button"][data-supervisor-brand]:is(:disabled, [aria-disabled="true"]) [data-supervisor-brand-arrow] {
  transform: rotate(135deg);
}

[data-slot="button"][data-supervisor-brand]:is(:disabled, [aria-disabled="true"]) [data-supervisor-brand-state="active"] {
  opacity: 0;
  transform: translateY(-60%);
}

[data-slot="button"][data-supervisor-brand]:is(:disabled, [aria-disabled="true"]) [data-supervisor-brand-state="selected"] {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="button"][data-supervisor-brand],
  [data-slot="button"][data-supervisor-brand] [data-supervisor-brand-arrow],
  [data-slot="button"][data-supervisor-brand] [data-supervisor-brand-state] {
    transition: none;
  }
  [data-slot="button"][data-supervisor-brand]:is(:hover, :active) {
    transform: none;
    translate: none;
    scale: none;
  }
}
